import pandas as pd
import pdfplumber

pop_path = '/root/population.pdf'
inc_path = '/root/income.xlsx'

rows = []
with pdfplumber.open(pop_path) as pdf:
    for page in pdf.pages:
        table = page.extract_table()
        if table:
            rows.extend(table)
rows = [r for r in rows if r and r[0] != 'SA2_CODE']

pop_df = pd.DataFrame(rows, columns=['SA2_CODE','SA2_NAME','STATE','POPULATION_2023'])

def norm_code(x):
    if pd.isna(x):
        return None
    try:
        return str(int(float(str(x).strip())))
    except Exception:
        return str(x).strip()

pop_df['SA2_CODE'] = pop_df['SA2_CODE'].map(norm_code)

inc_df = pd.read_excel(inc_path, sheet_name='Data')
inc_df['SA2_CODE'] = inc_df['SA2_CODE'].map(norm_code)

merged = inc_df.merge(pop_df[['SA2_CODE','STATE']], on='SA2_CODE', how='left')
missing = merged['STATE'].isna().sum()
print('missing_state_rows', missing)
